package com.yuegang.zhihui.product.api;
import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.util.*;
public record SaveProductRequest(@NotBlank String categoryId,String brandId,@NotBlank @Size(max=200)String name,@NotBlank @Size(max=64)String skuCode,@NotNull @DecimalMin("0.00")@Digits(integer=16,fraction=2)BigDecimal price,@NotBlank @Pattern(regexp="[A-Z]{3}")String currency,@NotNull @Size(max=20)List<@Size(max=512)String>images,@Size(max=128)String traceabilityCode,@PositiveOrZero long version,@Size(max=30)Map<@NotBlank @Size(max=64)String,@NotBlank @Size(max=200)String>specifications){public SaveProductRequest(String categoryId,String brandId,String name,String skuCode,BigDecimal price,String currency,List<String>images,String traceabilityCode,long version){this(categoryId,brandId,name,skuCode,price,currency,images,traceabilityCode,version,Map.of());}public SaveProductRequest{specifications=specifications==null?Map.of():Map.copyOf(specifications);}}
